func latestCheckpointID(sessions []exportSession) string {
	var latest exportSession
	for _, session := range sessions {
		if latest.SessionID == "" || shouldReplaceExportSession(latest, session) {
			latest = session
		}
	}
	return latest.LatestCheckpoint
